DELETE FROM INFRANEXUM_IAM_ROLE_PERMISSION WHERE PERMISSION_ID IN (SELECT ID FROM INFRANEXUM_IAM_PERMISSION WHERE CODE LIKE 'dcim.model.%' OR CODE LIKE 'dcim.rack.%' OR CODE LIKE 'dcim.equipment.%' OR CODE LIKE 'dcim.port.%' OR CODE LIKE 'dcim.cable.%');
DELETE FROM INFRANEXUM_IAM_PERMISSION WHERE ORGANIZATION_ID IS NULL AND (CODE LIKE 'dcim.model.%' OR CODE LIKE 'dcim.rack.%' OR CODE LIKE 'dcim.equipment.%' OR CODE LIKE 'dcim.port.%' OR CODE LIKE 'dcim.cable.%');
